    """
    Determine if predictions match actual match outcomes.
    Compare two equal-length arrays: actual scores and guesses.
    Return an array with 0 for accurate guesses, otherwise the absolute score difference.

    example:

    compare([1,2,3,4,5,1],[1,2,3,4,2,-2]) -> [0,0,0,0,3,3]
    compare([0,5,0,0,0,4],[4,1,1,0,0,-2]) -> [4,4,1,0,0,6]
    """
    results = []
    for i in range(len(game)):
        if game[i] == guess[i]:
            results.append(0)
        else:
            results.append(abs(game[i] - guess[i]))
    return results
